from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from .documents import WarehouseInventoryDocument

class InventoryCategoryFacetsView(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request):
        category = request.query_params.get("category", "")
        s = WarehouseInventoryDocument.search().filter("term", supplier_id=request.user.supplier_id)
        if category:
            s = s.filter("term", category=category)
        s.aggs.bucket("per_warehouse", "terms", field="warehouse_code")
        response = s.execute()

        aggregations = [
            {"warehouse": b.key, "item_count": b.doc_count}
            for b in response.aggregations.per_warehouse.buckets
        ]
        return Response({"category": category, "aggregations": aggregations})
